{
  "name": "Robo HAT MM1 电机与转向控制板",
  "name_en": "Robo HAT MM1 Motor and Steering Controller",
  "manufacturer": "Robotics Masters",
  "description": "用于机器人小车的PWM控制板，可将转向和油门指令转换为PWM脉冲输出，以驱动转向舵机和电机油门，并支持数值校验、限幅与安全关闭。",
  "description_en": "A PWM control board for robotic vehicles that converts steering and throttle commands into PWM pulse outputs to drive a steering servo and motor throttle, with value validation, clamping, and safe shutdown support.",
  "actions": [
    {
      "action_name": "auto-trim_out_of_bound_value",
      "description": "将超出允许范围的控制值裁剪到有效区间。",
      "description_en": "Clamp a control value that is outside the allowed range into the valid interval."
    },
    {
      "action_name": "auto-set_pulse",
      "description": "设置转向和油门的PWM脉冲值。",
      "description_en": "Set the PWM pulse values for steering and throttle."
    },
    {
      "action_name": "auto-is_valid_pwm_value",
      "description": "检查给定的PWM值是否有效。",
      "description_en": "Check whether a given PWM value is valid."
    },
    {
      "action_name": "auto-write_pwm",
      "description": "将转向和油门命令写入PWM输出。",
      "description_en": "Write steering and throttle commands to the PWM outputs."
    },
    {
      "action_name": "auto-run",
      "description": "执行一次转向和油门控制更新并输出PWM信号。",
      "description_en": "Perform one steering and throttle control update and output PWM signals."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭控制板输出以安全停止设备。",
      "description_en": "Shut down the controller outputs to safely stop the device."
    }
  ],
  "tag_hints": [
    "PWM motor control",
    "steering servo control",
    "throttle control",
    "Robo HAT MM1",
    "robot car controller",
    "RC pulse output"
  ]
}

